"use client";

import { FileSpreadsheet, Download } from "lucide-react";
import * as XLSX from "xlsx";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

export default function TombolCetak({ data, periode }: { data: any, periode: string }) {
  
  const exportToExcel = () => {
    // Menyusun data untuk Excel
    const dataSheet = [
      { Indikator: "UC (Urinary Catheter)", Hasil: data.uc || 0, Satuan: "Hari" },
      { Indikator: "CVL (Central Venous Line)", Hasil: data.cvl || 0, Satuan: "Hari" },
      { Indikator: "IVL (Intravenous Line)", Hasil: data.ivl || 0, Satuan: "Hari" },
      { Indikator: "ETT (Endotracheal Tube)", Hasil: data.ett || 0, Satuan: "Hari" },
      { Indikator: "VAP", Hasil: data.vap || 0, Satuan: "Pasien" },
      { Indikator: "HAP", Hasil: data.hap || 0, Satuan: "Pasien" },
      { Indikator: "ISK", Hasil: data.isk || 0, Satuan: "Pasien" },
      { Indikator: "IAD", Hasil: data.iad || 0, Satuan: "Pasien" },
      { Indikator: "Kultur Positif", Hasil: data.kultur_positif || 0, Satuan: "Pasien" },
      { Indikator: "Penggunaan ABX", Hasil: data.antibiotik || 0, Satuan: "Kali" },
    ];

    const worksheet = XLSX.utils.json_to_sheet(dataSheet);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Surveilans");
    XLSX.writeFile(workbook, `Laporan_Surveilans_RS_ARUN_${periode}.xlsx`);
  };

  const exportToPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(16);
    doc.text("LAPORAN SURVEILANS UNIT - RS ARUN", 14, 15);
    doc.setFontSize(10);
    doc.text(`Periode: ${periode}`, 14, 22);

    autoTable(doc, {
      startY: 30,
      head: [['Kategori', 'Indikator', 'Capaian']],
      body: [
        ['Tindakan', 'UC (Urinary Catheter)', `${data.uc || 0} Hari`],
        ['Tindakan', 'CVL (Central Venous Line)', `${data.cvl || 0} Hari`],
        ['Tindakan', 'IVL (Intravenous Line)', `${data.ivl || 0} Hari`],
        ['Tindakan', 'ETT (Endotracheal Tube)', `${data.ett || 0} Hari`],
        ['HAIs', 'VAP', `${data.vap || 0} Pasien`],
        ['HAIs', 'HAP', `${data.hap || 0} Pasien`],
        ['HAIs', 'ISK', `${data.isk || 0} Pasien`],
        ['HAIs', 'IAD', `${data.iad || 0} Pasien`],
        ['Penunjang', 'Kultur Positif', `${data.kultur_positif || 0} Pasien`],
        ['Penunjang', 'Antibiotik (ABX)', `${data.antibiotik || 0} Kali`],
      ],
      theme: 'grid',
      headStyles: { fillColor: [37, 99, 235] }
    });

    doc.save(`Laporan_Surveilans_RS_ARUN_${periode}.pdf`);
  };

  return (
    <div className="flex flex-col md:flex-row items-center gap-3 w-full md:w-auto order-1 md:order-2">
      <button 
        onClick={exportToExcel}
        className="w-full md:w-auto flex items-center justify-center gap-2 bg-emerald-600 text-white px-8 py-3.5 rounded-2xl text-xs font-bold hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-100"
      >
        <FileSpreadsheet size={18} /> Download Excel
      </button>
      <button 
        onClick={exportToPDF}
        className="w-full md:w-auto flex items-center justify-center gap-2 bg-red-600 text-white px-8 py-3.5 rounded-2xl text-xs font-bold hover:bg-red-700 transition-all shadow-lg shadow-red-100"
      >
        <Download size={18} /> Download PDF
      </button>
    </div>
  );
}